export type ImageLinkKey = keyof typeof IMAGE_LINKS;



export type PosterEndpointInput = {
  tmdbId?: number;
  imdbId?: string;
  title: string;
  originalTitle?: string;
  year?: string | number;
  type?: string;
};

function buildTmdbPosterEndpoint(input: PosterEndpointInput, version: string) {
  const params = new URLSearchParams();

  if (input.tmdbId) params.set("tmdbId", String(input.tmdbId));
  if (input.imdbId) params.set("imdbId", input.imdbId);
  params.set("title", input.title);
  if (input.originalTitle) params.set("originalTitle", input.originalTitle);
  if (input.year) params.set("year", String(input.year));
  if (input.type) params.set("type", String(input.type));
  params.set("quality", "high");
  params.set("v", version);

  return `/api/tmdb/poster?${params.toString()}`;
}

export function getTmdbPoster(input: PosterEndpointInput) {
  // v=3 нужен, чтобы браузер не держал старый 302-редирект на /kinoluma-icon.png.
  return buildTmdbPosterEndpoint(input, "3");
}

export function getGeneratedTmdbPoster(input: PosterEndpointInput) {
  return buildTmdbPosterEndpoint(input, "generated-500");
}

export function getGeneratedCartoonPoster(input: PosterEndpointInput) {
  return buildTmdbPosterEndpoint(input, "generated-cartoons");
}

export function getManualAnimePoster(input: PosterEndpointInput) {
  return buildTmdbPosterEndpoint(input, "manual-anime-2");
}

export function getManualPremiumPoster(input: PosterEndpointInput) {
  return buildTmdbPosterEndpoint(input, "manual-premium-2");
}

export function getTmdbExpectedPoster(input: PosterEndpointInput) {
  return buildTmdbPosterEndpoint(input, "expected-curated-1");
}

export function getKinopoiskPoster(input: {
  kinopoiskId?: number | string | null;
  fallback?: string;
}) {
  const id = String(input.kinopoiskId || "").match(/\d+/)?.[0] || "";
  if (!id) return input.fallback || "/kinoluma-icon.png";

  const params = new URLSearchParams();
  params.set("kpId", id);
  // v=kp-2 нужен, чтобы браузер и Vercel не держали старый 302-редирект на /kinoluma-icon.png.
  params.set("v", "kp-2");

  if (input.fallback && !input.fallback.startsWith("data:")) {
    params.set("fallback", input.fallback);
  }

  return `/api/kinopoisk/poster?${params.toString()}`;
}

export function getGeneratedKinopoiskPoster(kinopoiskId: number | string, version = "kp-generated-1") {
  const params = new URLSearchParams();
  params.set("kpId", String(kinopoiskId));
  params.set("v", version);

  return `/api/kinopoisk/poster?${params.toString()}`;
}

function escapePosterText(text: string) {
  return text
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&apos;");
}

function splitPosterLine(text: string, maxLength: number, maxLines: number) {
  const words = text.split(" ").filter(Boolean);
  const lines: string[] = [];

  for (const word of words) {
    const currentLine = lines[lines.length - 1];

    if (!currentLine) {
      lines.push(word);
      continue;
    }

    if (`${currentLine} ${word}`.length <= maxLength) {
      lines[lines.length - 1] = `${currentLine} ${word}`;
      continue;
    }

    if (lines.length < maxLines) {
      lines.push(word);
    }
  }

  return lines.length > 0 ? lines.slice(0, maxLines) : [text];
}

