export function buildTmdbImageUrl(
  path: string | null | undefined,
  size = "w500",
): string | null {
  if (!path) return null;
  if (path.startsWith("http")) return path;
  return `${IMAGE_SOURCE_LINKS.tmdbImageBase}/${size}${path}`;
}

export function buildTmdbOriginalImageUrl(path: string | null | undefined): string | null {
  if (!path) return null;
  if (path.startsWith("http")) return path;
  return `${IMAGE_SOURCE_LINKS.tmdbImageOriginalBase}${path}`;
}
